// Caller holds the environment lease. Withdraw before any persistent operation.
const withdrawPlatformEnvironmentLocked = Effect.fn("EnvironmentRegistry.withdrawPlatformEnvironmentLocked")(
  function* (environmentId: EnvironmentId, incoming?: ConnectionCatalogEntry) {
    const entry = (yield* SubscriptionRef.get(entries)).get(environmentId) ?? incoming;
    const connectionIds = new Set([
      ...(pendingPlatformCleanup.get(environmentId) ?? []),
      ...[entry, incoming].flatMap((candidate) => candidate === undefined ? []
        : connectionRoutes(candidate).flatMap((route) => route.target._tag === "BearerConnectionTarget"
          ? [credentialConnectionId(route.target.connectionId)] : [])),
    ]);
    pendingPlatformCleanup.set(environmentId, connectionIds);
    yield* Ref.update(platformEnvironmentIds, (current) => new Set(current).add(environmentId));
    yield* SubscriptionRef.update(entries, (current) => {
      const next = new Map(current);
      next.delete(environmentId);
      return next;
    });
    yield* closeServiceScope(environmentId);

    const persisted = (yield* Ref.get(persistedEnvironmentIds)).has(environmentId);
    const results = yield* Effect.forEach([
      pullRequestRoutingPermissions.forget(environmentId),
      ...[...connectionIds].map((connectionId) => credentials.remove(connectionId)),
      cache.clear(environmentId),
      ownedDataCleanup.clear(environmentId),
      ...(persisted ? [registrations.remove(environmentId)] : []),
    ], (cleanup) => cleanup.pipe(Effect.exit), { concurrency: "unbounded" });
    if (results.some(Exit.isFailure)) {
      yield* Effect.logWarning("Platform environment withdrawn; cleanup needs retry.", { environmentId });
      return false;
    }
    pendingPlatformCleanup.delete(environmentId);
    yield* Ref.update(platformEnvironmentIds, (current) => {
      const next = new Set(current);
      next.delete(environmentId);
      return next;
    });
    yield* Ref.update(persistedEnvironmentIds, (current) => {
      const next = new Set(current);
      next.delete(environmentId);
      return next;
    });
    return true;
  },
);

const removePlatformEnvironment = (environmentId: EnvironmentId) =>
  withLeaseLock(environmentId, withdrawPlatformEnvironmentLocked(environmentId));

